/**
 * Fixture responses for the mock backend. `scan-*.json` and `app-info.json`'s ruleCount are
 * generated by the real engine (`tools/gen-ui-fixtures.sh`, which pipes the demo inputs through
 * `scrub --json`); the rest are hand-written.
 * `tests/unit/fixtures.test.ts` validates every file against `lib/schema.ts`.
 */
import type { AppInfo, ClipboardScrub, ScanResponse, SessionSecret, Settings } from '../types';
import appInfo from './fixtures/app-info.json';
import clipboardCleaned from './fixtures/clipboard-cleaned.json';
import clipboardProtected from './fixtures/clipboard-protected.json';
import scanDemo from './fixtures/scan-demo.json';
import scanEmpty from './fixtures/scan-empty.json';
import scanHarsh from './fixtures/scan-harsh.json';
import settings from './fixtures/settings.json';
import sessionDemo from './fixtures/session-demo.json';

// JSON imports widen string unions to `string`; the schema test guarantees the narrow types.
const as = <T>(v: unknown): T => v as T;

export const FIXTURES = {
  'app-info': as<AppInfo>(appInfo),
  'clipboard-cleaned': as<ClipboardScrub>(clipboardCleaned),
  'clipboard-protected': as<ClipboardScrub>(clipboardProtected),
  'scan-demo': as<ScanResponse>(scanDemo),
  'scan-empty': as<ScanResponse>(scanEmpty),
  'scan-harsh': as<ScanResponse>(scanHarsh),
  settings: as<Settings>(settings),
  'session-demo': as<SessionSecret[]>(sessionDemo),
} as const;

export type FixtureName = keyof typeof FIXTURES;

/** Deep copy, so mock state never mutates the imported fixture. */
export function fixture<K extends FixtureName>(name: K): (typeof FIXTURES)[K] {
  return structuredClone(FIXTURES[name]);
}
